INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-exam-linear-algebra-set-04-s2-5', 'exam-linear-algebra-set-04', 'exam-linear-algebra-set-04-sec-2', 3, '求的值,使实二次型为正定二次型', '求 $\\lambda$ 的值, 使实二次型 $f(x_{1}, x_{2}, x_{3}) = x_{1}^{2} + 4x_{2}^{2} + 2x_{3}^{2} + 2\\lambda x_{1}x_{2} + 2x_{1}x_{3}$ 为正定二次型.
